import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#world'), shell=document.querySelector('#game-shell');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#bfe5f8'); scene.fog=new THREE.FogExp2('#c9e6ed',.0095);
const camera=new THREE.PerspectiveCamera(43,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight('#e9f8ff','#718e67',2.1));
const sun=new THREE.DirectionalLight('#fff0d6',3.3); sun.position.set(-16,28,12); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-42; sun.shadow.camera.right=42; sun.shadow.camera.top=42; sun.shadow.camera.bottom=-42; sun.shadow.bias=-.0002; scene.add(sun);
const mats={}; function mat(color,roughness=.82,extra={}){let key=color+roughness;if(!extra.emissive&&!mats[key])mats[key]=new THREE.MeshStandardMaterial({color,roughness,...extra});return extra.emissive?new THREE.MeshStandardMaterial({color,roughness,...extra}):mats[key]}
function box(parent,x,y,z,w,h,d,color,opts={}){let m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color,.86,opts));m.position.set(x,y,z);m.castShadow=opts.cast!==false;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,sx,sy,sz,color,opts={}){let m=new THREE.Mesh(new THREE.SphereGeometry(1,opts.seg||18,opts.seg||14),mat(color,.74,opts));m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cyl(parent,x,y,z,rt,rb,h,color,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function group(parent,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
function cone(parent,x,y,z,r,h,color,segments=8){let m=new THREE.Mesh(new THREE.ConeGeometry(r,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
// Soft, painterly town ground and winding road.
const ground=new THREE.Mesh(new THREE.PlaneGeometry(150,160),mat('#86b983'));ground.rotation.x=-Math.PI/2;ground.position.set(0,-.08,-30);ground.receiveShadow=true;scene.add(ground);
for(let i=0;i<38;i++){const x=(Math.random()-.5)*95,z=-74+Math.random()*91;const b=sphere(scene,x,.015,z,.12+Math.random()*.3,.018,.1+Math.random()*.16,i%3?'#a2c891':'#bad39b',{cast:false});}
// Curving cream stone road with subtly inset joints.
const roadShape=new THREE.Shape();roadShape.moveTo(-5.3,12);roadShape.lineTo(5.3,12);roadShape.lineTo(4.5,-18);roadShape.quadraticCurveTo(3,-27,4.7,-40);roadShape.lineTo(6.2,-90);roadShape.lineTo(-6.2,-90);roadShape.lineTo(-4.7,-40);roadShape.quadraticCurveTo(-3,-27,-4.5,-18);roadShape.close();const road=new THREE.Mesh(new THREE.ShapeGeometry(roadShape,32),mat('#e2d6b7'));road.rotation.x=-Math.PI/2;road.position.y=.008;road.receiveShadow=true;scene.add(road);
const roadEdge=mat('#bdc6a1');for(const side of [-1,1]){const curb=box(scene,side*5.45,.09,-35,.22,.15,95,'#b7bda0');curb.rotation.y=side*.015;}
for(let z=9;z>-88;z-=3.5){box(scene,0,.017,z,.07,.012,.08,'#c7bea5',{cast:false});}
// building architecture, shutters, trim and gabled rooftops.
function house(x,z,scale=1,paint='#efcda2',roof='#c66f51',type='home'){
 const g=group(scene,x,0,z);const w=type==='shop'?7:5.7,d=type==='shop'?5.4:5,h=type==='shop'?4.4:3.8;
 box(g,0,h/2,0,w*scale,h*scale,d*scale,paint);box(g,0,h*scale+.04,0,(w+.35)*scale,.18*scale,(d+.35)*scale,'#f8e9ca');
 const roofGeom=new THREE.ConeGeometry(w*.77*scale,h*.52*scale,4);const r=new THREE.Mesh(roofGeom,mat(roof));r.position.set(0,h*scale+h*.25*scale,0);r.rotation.y=Math.PI/4;r.scale.z=(d/w);r.castShadow=true;g.add(r);
 // front facade is toward camera / road
 box(g,0,.14, d*.51*scale,w*.83*scale,.19*scale,.16*scale,'#9b795a');
 for(const sx of [-1,1]){box(g,sx*w*.28*scale,h*.58*scale,d*.51*scale,.9*scale,1.22*scale,.075*scale,'#84bcc0');box(g,sx*w*.28*scale,h*.58*scale,d*.51*scale,.1*scale,1.28*scale,.1*scale,'#fff0d7');box(g,sx*w*.28*scale,h*.58*scale,d*.51*scale,.98*scale,.1*scale,.1*scale,'#fff0d7');box(g,sx*w*.28*scale,h*.58*scale,d*.55*scale,1.04*scale,.12*scale,.17*scale,'#ae7f5a');}
 box(g,0,.95*scale,d*.51*scale,.85*scale,1.9*scale,.12*scale,type==='shop'?'#6d9e8a':'#987151');sphere(g,0,1.76*scale,d*.59*scale,.06,.06,.04,'#f3d9a8');
 if(type==='shop'){box(g,0,h*.84*scale,d*.51*scale,2.1*scale,.47*scale,.13,'#fff1cf');for(let i=-1;i<=1;i++)box(g,i*.65*scale,h*.84*scale+.25,d*.51*scale,.36*scale,.07,.14,'#de8f58');}
 return g;
}
house(-10,-5,1.2,'#f3d2a7','#c77c59');house(10,-2,1.2,'#d7e5bc','#bd7857');house(-11,-17,.95,'#dfc4a0','#9e6654');house(11,-16,1.05,'#e8c1a8','#a85f54');house(-13,-31,1.15,'#f2d5a5','#c58a56','shop');house(13,-32,1.15,'#c5dfd1','#8a645a','shop');
// buildings distant in silhouette
for(let i=0;i<8;i++){const x=(i%2?1:-1)*(16+Math.floor(i/2)*4),z=-44-Math.floor(i/2)*10;house(x,z,.65+Math.random()*.22,['#e7d2ad','#c9ddce','#edc6a8'][i%3],['#a96857','#8b7765','#b67955'][i%3]);}
// sidewalk flower pots and fences
function tree(x,z,size=1,flower=false){const t=group(scene,x,0,z);cyl(t,0,.8*size,0,.23*size,.32*size,1.6*size,'#8e6846',9);sphere(t,0,2.1*size,0,1.05*size,1.12*size,.95*size,flower?'#8fb878':'#6f9e68');sphere(t,-.6*size,1.9*size,.12*size,.58*size,.7*size,.6*size,flower?'#a2c57d':'#80ad70');sphere(t,.53*size,2.35*size,-.1*size,.63*size,.72*size,.66*size,flower?'#789f69':'#78a56a');if(flower){for(let i=0;i<5;i++)sphere(t,Math.cos(i*1.25)*.46*size,2.35*size+Math.sin(i*1.25)*.44*size,.63*size,.11*size,.11*size,.07*size,['#f2c469','#f7e5b3','#e9a596'][i%3]);}return t;}
for(let z=4;z>-42;z-=9){tree(-8.1,z,.8+(z%3)*.025,z%2===0);tree(8.1,z,.9,z%3===0);}
for(let i=0;i<8;i++){const z=-8-i*4;box(scene,-6.8,.35,z,.12,.7,.12,'#b79669');box(scene,-7.8,.35,z,.12,.7,.12,'#b79669');box(scene,-7.3,.25,z,.9,.09,.11,'#ddc9a1');box(scene,-7.3,.52,z,.9,.09,.11,'#ddc9a1');}
// street lanterns
for(const z of [-3,-13,-23,-34])for(const x of [-6.4,6.4]){cyl(scene,x,1.6,z,.055,.085,3.2,'#64776b');box(scene,x,3.22,z,.52,.09,.42,'#556a61');const lamp=sphere(scene,x,3.48,z,.22,.23,.22,'#fff0b0',{emissive:'#ffe4a0',emissiveIntensity:1.2});}
// League arena, a welcoming stone-and-glass landmark on the far avenue.
const arena=group(scene,0,0,-52);cyl(arena,0,.18,0,11,11,.36,'#d2c49f',40);cyl(arena,0,.48,0,9.3,9.3,.32,'#eee2c6',40);cyl(arena,0,1.9,0,8.5,9.2,2.65,'#d8e6d9',32);cyl(arena,0,1.2,0,9.25,9.25,.25,'#b78d61',32);cyl(arena,0,3.3,0,9.4,8.8,.35,'#f5e4bd',32);
for(let i=0;i<16;i++){const a=i*Math.PI/8,x=Math.cos(a)*8.55,z=Math.sin(a)*8.55;cyl(arena,x,2.1,z,.22,.28,2.4,'#e9d8b5',8);sphere(arena,x,3.4,z,.3,.28,.3,'#e0ad5d');}
const dome=new THREE.Mesh(new THREE.SphereGeometry(8.35,32,14,0,Math.PI*2,0,Math.PI/2),new THREE.MeshStandardMaterial({color:'#86c8c0',roughness:.43,metalness:.08,transparent:true,opacity:.76}));dome.position.y=3.45;dome.castShadow=true;arena.add(dome);
cyl(arena,0,.78,0,5.4,5.4,.15,'#c9b993',40);const battleRing=cyl(arena,0,.89,0,4.9,4.9,.12,'#d9d4b8',40);battleRing.material=mat('#d9d4b8');cyl(arena,0,.97,0,3.6,3.6,.08,'#a5cfb6',40);
// front entrance and sign
box(arena,0,1.45,8.55,3.1,2.6,.4,'#f2dfb6');box(arena,0,1.1,8.79,1.15,2.1,.22,'#668b80');box(arena,0,3.2,8.82,3.8,.54,.27,'#edbb6b');
// clouds and distant soft green hills.
for(let i=0;i<15;i++){const x=(i-7)*13,z=-74-Math.random()*30;const h=new THREE.Mesh(new THREE.SphereGeometry(1,12,10),mat(i%2?'#9bbb88':'#a8c691'));h.position.set(x,.5,z);h.scale.set(9+Math.random()*5,3+Math.random()*3,8);h.receiveShadow=true;scene.add(h);}
for(let i=0;i<10;i++){let cloud=group(scene,-40+Math.random()*80,15+Math.random()*8,-50+Math.random()*-20);for(let j=0;j<4;j++)sphere(cloud,j*.85,Math.sin(j)*.25,0,1.2,.43,.48,'#f4fcff',{cast:false});}

// Hand-built, fully articulated creature companions (original designs, no external assets).
const creatureSpecs={embercub:{name:'Embercub',type:'FIRE',color:'#e98151',belly:'#f5c27e',accent:'#f7bd4f',hp:84,level:12,moves:[['Cinder Dash','FIRE',20],['Bright Spark','FIRE',25],['Pounce','NORMAL',14],['Warm Up','BOOST',0]]},tidefin:{name:'Tidefin',type:'WATER',color:'#57a9bb',belly:'#dbede1',accent:'#75d3d9',hp:91,level:11,moves:[['Ripple Rush','WATER',19],['Bubble Pop','WATER',24],['Fin Flick','NORMAL',15],['Tidal Focus','BOOST',0]]},mossaur:{name:'Mossaur',type:'GRASS',color:'#7aaf73',belly:'#d6e5a5',accent:'#e3c66e',hp:102,level:10,moves:[['Vine Whip','GRASS',21],['Sunbeam','GRASS',26],['Headbutt','NORMAL',15],['Root Guard','BOOST',0]]},frostfang:{name:'Frostfang',type:'ICE',color:'#87bad1',belly:'#e3f2f2',accent:'#d8f6fa',hp:100,level:18,moves:[['Glacier Bite','ICE',17],['Snowstorm','ICE',21],['Quick Claw','NORMAL',14]]}};
function makeMonster(kind){const spec=creatureSpecs[kind],root=group(scene);const body=group(root);root.userData.body=body;root.userData.kind=kind;root.userData.anim=[];
 const fur=spec.color,belly=spec.belly,accent=spec.accent;
 if(kind==='embercub'||kind==='frostfang'){
  sphere(body,0,.94,0,.77,.7,.63,fur);sphere(body,0,.78,.47,.49,.38,.2,belly);sphere(body,0,1.76,.18,.59,.56,.52,fur);sphere(body,0,1.51,.59,.38,.22,.19,belly);
  for(const s of [-1,1]){const ear=cone(body,s*.42,2.35,.17,.22,.68,fur,7);ear.rotation.z=-s*.18;const inner=sphere(body,s*.42,2.38,.33,.09,.22,.05,kind==='embercub'?'#ffba73':'#d6f1f8');eye(body,s*.24,1.87,.635);sphere(body,s*.45,1.62,.55,.18,.12,.08,accent);}
  const tail=group(body,-.63,1.1,-.38);tail.rotation.z=.5; sphere(tail,-.36,.1,-.05,.48,.2,.2,fur);const tip=cone(tail,-.73,.14,-.05,.24,.52,kind==='embercub'?'#ffc653':'#c7eef4',8);tip.rotation.z=Math.PI/2;root.userData.tail=tail;
  if(kind==='embercub'){const flame=cone(tail,-.93,.16,-.05,.17,.4,'#ffb545',7);flame.rotation.z=Math.PI/2;}
 }else if(kind==='tidefin'){
  sphere(body,0,.95,0,.76,.76,.79,fur);sphere(body,0,.72,.57,.45,.43,.3,belly);sphere(body,0,1.77,.16,.55,.55,.51,fur);sphere(body,0,1.52,.59,.33,.19,.15,belly);
  for(const s of [-1,1]){sphere(body,s*.52,.91,.12,.2,.42,.3,fur).rotation.z=s*.45;const fin=cone(body,s*.57,.76,-.16,.22,.54,accent,7);fin.rotation.z=s*.5;eye(body,s*.22,1.85,.61);sphere(body,s*.4,1.61,.62,.13,.09,.05,'#89dce0');}
  const fin=cone(body,0,2.32,-.05,.24,.5,accent,7);fin.rotation.z=.15;const tail=cone(body,0,.9,-.85,.3,.62,accent,6);tail.rotation.x=Math.PI/2;root.userData.tail=tail;
 }else{
  sphere(body,0,.96,0,.8,.82,.66,fur);sphere(body,0,.72,.45,.52,.45,.3,belly);sphere(body,0,1.77,.22,.57,.55,.53,fur);sphere(body,0,1.53,.61,.35,.2,.16,belly);
  for(const s of [-1,1]){sphere(body,s*.26,1.83,.68,.07,.09,.04,'#514b3c');sphere(body,s*.44,2.34,.08,.23,.49,.22,'#76a879');sphere(body,s*.44,2.4,.22,.1,.25,.06,'#cfb982');eye(body,s*.23,1.86,.68);sphere(body,s*.42,1.62,.62,.14,.08,.05,accent);}
  for(let i=0;i<3;i++){const leaf=cone(body,0,2.3+i*.16,-.14-i*.04,.3-i*.045,.65,'#82b96e',6);leaf.rotation.x=-.8;}
  const tail=group(body,0,1,-.5);tail.rotation.x=-.3; sphere(tail,0,-.25,-.25,.25,.46,.3,'#6d9d65');const leaf=cone(tail,0,-.69,-.48,.33,.58,'#89bd72',6);leaf.rotation.x=-.7;root.userData.tail=tail;
 }
 // Face with bright pupils and a tiny curved smile.
 function eye(parent,x,y,z){sphere(parent,x,y,z,.105,.115,.065,'#f9f4dc');sphere(parent,x,y,z+.055,.052,.072,.036,'#263d46');sphere(parent,x-.018,y+.03,z+.084,.018,.02,.015,'#fff');}
 // paws have individual pivots so each partner has a visible walk cycle.
 root.userData.legs=[];for(const x of [-.42,.42]){const leg=group(body,x,.48,.08);sphere(leg,0,-.16,0,.19,.34,.2,fur);sphere(leg,0,-.36,.12,.23,.13,.3,belly);root.userData.legs.push(leg);}
 root.userData.bobPhase=Math.random()*6.28;return root;
}
const party=['embercub','tidefin','mossaur'].map(makeMonster);party.forEach((m,i)=>{m.position.set(-1.05+i*1.05,.02,10.2+Math.abs(i-1)*.52);m.scale.setScalar(i===0? .78:.59);m.userData.exploreScale=m.scale.x;});
function makeTrainer(){const g=group(scene,0,0,8.5);g.userData.legs=[];sphere(g,0,1.06,0,.37,.53,.28,'#e5a66f');box(g,0,1.02,-.25,.55,.65,.25,'#537d81');sphere(g,0,1.94,.04,.32,.37,.31,'#eab787');sphere(g,0,2.18,.03,.35,.17,.34,'#e4ad55');box(g,0,2.28,.05,.79,.12,.68,'#e4ad55');for(const s of [-1,1]){const arm=sphere(g,s*.39,1.1,0,.15,.4,.16,'#f1bb88');arm.rotation.z=s*.22;const leg=group(g,s*.17,.58,0);box(leg,0,-.18,0,.2,.48,.22,'#425f71');box(leg,0,-.42,.07,.27,.12,.36,'#e8e2d0');g.userData.legs.push(leg);}return g;}
const trainer=makeTrainer();
function eye(parent,x,y,z){sphere(parent,x,y,z,.105,.115,.065,'#f9f4dc');sphere(parent,x,y,z+.055,.052,.072,.036,'#263d46');sphere(parent,x-.018,y+.03,z+.084,.018,.02,.015,'#fff');}
const enemy=makeMonster('frostfang');enemy.position.set(2.7,.06,-51.8);enemy.rotation.y=-Math.PI/2;enemy.scale.setScalar(1.05);enemy.userData.exploreScale=1.05;
const particles=[];function burst(color,x,y,z,count=14){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.055+Math.random()*.09,8,7),new THREE.MeshBasicMaterial({color,transparent:true}));mesh.position.set(x,y,z);scene.add(mesh);particles.push({mesh,v:new THREE.Vector3((Math.random()-.5)*4,1+Math.random()*4,(Math.random()-.5)*4),life:.55+Math.random()*.5});}}
let state='explore',activeIndex=0,enemyHp=100,playerHp=84,acting=false,win=false,sound=true,camAngle=0,camDistance=11,dragging=false,prevX=0;let move={forward:false,back:false,left:false,right:false};let walkT=0;
const hpBars={enemy:document.querySelector('#enemy-hp-bar'),player:document.querySelector('#player-hp-bar')};
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),1900)}
function updatePartyRail(){party.forEach((m,i)=>{const hp=m.userData.hp??creatureSpecs[m.userData.kind].hp;const el=document.querySelectorAll('.mini-hp i')[i];if(el)el.style.width=`${hp/creatureSpecs[m.userData.kind].hp*100}%`})}
party.forEach(m=>m.userData.hp=creatureSpecs[m.userData.kind].hp);
function startBattle(){if(state!=='explore')return;state='battle';shell.classList.add('battling');document.querySelector('#battle-overlay').classList.add('active');document.querySelector('#battle-overlay').setAttribute('aria-hidden','false');document.querySelector('#world-hint').style.display='none';enemyHp=100;win=false;acting=false;document.querySelector('#battle-result').classList.remove('show');party.forEach((m,i)=>{m.position.set(-2.8,.08,-51.8);m.rotation.y=Math.PI/2;m.visible=i===activeIndex;m.scale.setScalar(i===activeIndex?.94:.8)});enemy.visible=true;enemy.position.set(2.8,.08,-51.8);enemy.rotation.y=-Math.PI/2;enemy.scale.setScalar(1.05);showBattleUI();
 document.querySelector('#battle-message').innerHTML='<span class="message-star">✦</span><span>Champion Nova sends out Frostfang! Choose your move.</span>';
}
function showBattleUI(){const spec=creatureSpecs[party[activeIndex].userData.kind];playerHp=party[activeIndex].userData.hp;document.querySelector('#active-name').textContent=spec.name;document.querySelector('#active-level').textContent=`LV. ${spec.level} · ${spec.type}`;document.querySelector('#player-hp-text').textContent=`${playerHp} / ${spec.hp}`;document.querySelector('#enemy-hp-text').textContent=`${Math.max(0,enemyHp)} / 100`;hpBars.player.style.width=`${playerHp/spec.hp*100}%`;hpBars.enemy.style.width=`${enemyHp}%`;hpBars.enemy.style.background=enemyHp<30?'#df9272':'#81bb79';const grid=document.querySelector('#move-grid');grid.innerHTML='';spec.moves.forEach(([name,type,power])=>{const b=document.createElement('button');b.className='move-button';b.innerHTML=`<span class="move-type">${type==='BOOST'?'✧':type==='FIRE'?'🔥':type==='WATER'?'◉':type==='GRASS'?'❋':type==='ICE'?'❄':'✦'}</span><b>${name}</b><small>${type==='BOOST'?'Restore 12 HP':'POWER  '+power}</small>`;b.disabled=acting;b.onclick=()=>attack(name,type,power);grid.appendChild(b)});updatePartyRail();}
function setMessage(text){document.querySelector('#battle-message').innerHTML=`<span class="message-star">✦</span><span>${text}</span>`}
function attack(name,type,power){if(state!=='battle'||acting||win)return;acting=true;const actor=party[activeIndex],kind=actor.userData.kind,spec=creatureSpecs[kind];if(type==='BOOST'){const heal=Math.min(spec.hp-actor.userData.hp,12);actor.userData.hp+=heal;setMessage(`${spec.name} finds its focus and restores ${heal} HP!`);showBattleUI();acting=true;setTimeout(enemyTurn,750);return;}
 const strong=(type==='FIRE'&&creatureSpecs.frostfang.type==='ICE')||(type==='WATER'&&false)||(type==='GRASS'&&false);let damage=power+Math.floor(Math.random()*7)+(strong?12:0);enemyHp=Math.max(0,enemyHp-damage);actor.position.x=-2.8+.75;setTimeout(()=>actor.position.x=-2.8,180);burst(type==='FIRE'?'#ffac51':type==='WATER'?'#77d5e6':type==='GRASS'?'#a1cf77':'#f6d787',2.4,1.35,-51.1,18);document.querySelector('#battle-flash').classList.remove('hit');void document.querySelector('#battle-flash').offsetWidth;document.querySelector('#battle-flash').classList.add('hit');setMessage(`${spec.name} used ${name}! ${strong?'It is super effective! ':''}Frostfang took ${damage} damage.`);showBattleUI();acting=true;if(enemyHp<=0){setTimeout(victory,850);return;}setTimeout(enemyTurn,920);}
function enemyTurn(){if(state!=='battle'||win)return;const actor=party[activeIndex],spec=creatureSpecs[actor.userData.kind];const damage=9+Math.floor(Math.random()*9);actor.userData.hp=Math.max(0,actor.userData.hp-damage);playerHp=actor.userData.hp;enemy.position.x=2.8-.5;setTimeout(()=>enemy.position.x=2.8,190);burst('#ade7f0',-2.2,1.3,-51.15,12);setMessage(`Frostfang used Glacier Bite! ${spec.name} took ${damage} damage.`);showBattleUI();if(playerHp<=0){const next=party.findIndex((m,i)=>i!==activeIndex&&m.userData.hp>0);if(next>=0){setTimeout(()=>{activeIndex=next;party.forEach((m,i)=>m.visible=i===activeIndex);showBattleUI();setMessage(`${spec.name} needs a rest. Go, ${creatureSpecs[party[next].userData.kind].name}!`);acting=false},700);}else{setTimeout(()=>{party.forEach(m=>m.userData.hp=creatureSpecs[m.userData.kind].hp);activeIndex=0;showBattleUI();setMessage('Your partners are ready to try again! Choose a move.');acting=false},800);return;} }acting=false;showBattleUI();}
