console.log('moves:', await page.locator('.move-button').count());
await page.locator('#switch-button').click();
console.log('switch options:', await page.locator('.switch-option').count());
await page.locator('.switch-option:not(:disabled)').first().click();
await page.waitForTimeout(850);
console.log('active partner:', await page.locator('#active-name').textContent());
await page.locator('.move-button').first().click();
await page.waitForTimeout(900);
console.log('enemy health after turn:', await page.locator('#enemy-hp-text').textContent());
await page.locator('#exit-battle').click();
console.log('battle closed:', await page.locator('#battle-overlay').getAttribute('aria-hidden'));
console.log('page errors:', errors);
await browser.close();
